/**
 * Where the Jellyfin token lives in a browser (F5, ADR 0008). A browser has no keychain, so this is
 * the most secure place available: the session is encrypted with AES-GCM under a key generated by
 * Web Crypto as non-extractable and kept in IndexedDB. Script on this origin can use the key through
 * the API but can never read its bytes, so the stored blob is useless anywhere else and the token is
 * never written in clear text. Web Crypto only exists on secure origins (https or localhost); on a
 * plain http origin the session is stored unencrypted and Settings says so (`mode: 'plain'`).
 */
import { Server } from '@renaissance/core';
import type { Session } from '@renaissance/core';
import { openDB } from 'idb';
import type { DBSchema, IDBPDatabase } from 'idb';
import { z } from 'zod';

const DB_NAME = 'renaissance-vault';
const KEY_ID = 'session-key';
const SESSION_ID = 'session';

export type VaultMode = 'encrypted' | 'plain';

const StoredSession = z.object({
  server: Server,
  userId: z.string().min(1),
  userName: z.string().min(1),
  token: z.string().min(1),
});

interface VaultSchema extends DBSchema {
  keys: { key: string; value: CryptoKey };
  sessions: {
    key: string;
    value: { mode: VaultMode; iv?: ArrayBuffer; data: ArrayBuffer | string };
  };
}

function hasCrypto(): boolean {
  return typeof crypto !== 'undefined' && !!crypto.subtle && typeof indexedDB !== 'undefined';
}

/** True when the token can be encrypted here (a secure context with Web Crypto). */
export function vaultMode(): VaultMode {
  return hasCrypto() && (typeof isSecureContext === 'undefined' || isSecureContext)
    ? 'encrypted'
    : 'plain';
}

function open(): Promise<IDBPDatabase<VaultSchema>> {
  return openDB<VaultSchema>(DB_NAME, 1, {
    upgrade(db) {
      db.createObjectStore('keys');
      db.createObjectStore('sessions');
    },
  });
}

async function sessionKey(db: IDBPDatabase<VaultSchema>): Promise<CryptoKey> {
  const existing = await db.get('keys', KEY_ID);
  if (existing) return existing;
  const key = await crypto.subtle.generateKey({ name: 'AES-GCM', length: 256 }, false, [
    'encrypt',
    'decrypt',
  ]);
  await db.put('keys', key, KEY_ID);
  return key;
}

export async function saveSession(session: Session): Promise<VaultMode> {
  const db = await open();
  try {
    const json = JSON.stringify(StoredSession.parse(session));
    if (vaultMode() === 'encrypted') {
      const key = await sessionKey(db);
      const iv = crypto.getRandomValues(new Uint8Array(12));
      const data = await crypto.subtle.encrypt(
        { name: 'AES-GCM', iv },
        key,
        new TextEncoder().encode(json),
      );
      await db.put('sessions', { mode: 'encrypted', iv: iv.buffer, data }, SESSION_ID);
      return 'encrypted';
    }
    await db.put('sessions', { mode: 'plain', data: json }, SESSION_ID);
    return 'plain';
  } finally {
    db.close();
  }
}

/** The stored session, or null when there is none or it cannot be read (then it is cleared). */
export async function loadSession(): Promise<{ session: Session; mode: VaultMode } | null> {
  if (typeof indexedDB === 'undefined') return null;
  const db = await open();
  try {
    const record = await db.get('sessions', SESSION_ID);
    if (!record) return null;
    let json: string;
    if (record.mode === 'encrypted') {
      if (!hasCrypto() || !record.iv || typeof record.data === 'string') return null;
      const key = await db.get('keys', KEY_ID);
      if (!key) return null;
      const plain = await crypto.subtle.decrypt(
        { name: 'AES-GCM', iv: new Uint8Array(record.iv) },
        key,
        record.data,
      );
      json = new TextDecoder().decode(plain);
    } else {
      json = typeof record.data === 'string' ? record.data : '';
    }
    const parsed = StoredSession.safeParse(JSON.parse(json));
    if (!parsed.success) {
      await db.delete('sessions', SESSION_ID);
      return null;
    }
    return { session: parsed.data, mode: record.mode };
  } catch {
    await db.delete('sessions', SESSION_ID).catch(() => undefined);
    return null;
  } finally {
    db.close();
  }
}

export async function clearSession(): Promise<void> {
  if (typeof indexedDB === 'undefined') return;
  const db = await open();
  try {
    await db.delete('sessions', SESSION_ID);
  } finally {
    db.close();
  }
}
